/**
 * 启发式只认「指令」（正则正侧）。
 * 「问题」不得由正则认定 → 返回 undetermined，交意图 LLM 判定后才可 auto_flow。
 */
export function classifyUtterance(
  userText: string,
): 'instruction' | 'undetermined' {
  const t = userText.trim()
  if (!t) return 'undetermined'
  // 指令：调显 / 单启工种 / 跳过匹配 / 匹配确认 / 监督归因口令
  if (
    /^(显示|打开|调取|展开|看看|只看)/.test(t) ||
    /请?(跑|启|开|执行|重跑)?\s*(peek|decide|infer|query|reuse|监督)/i.test(t) ||
    /单启|单独跑|只跑|跳过匹配|监督匹配|确认匹配|path\s*匹配|深化|收窄|监督归因|不满|换方向|换推|推理不对|预测不对|材料不够|换问|改问|问法不对/.test(t) ||
    /^(noop|通过)\s*$/i.test(t)
  ) {
    return 'instruction'
  }
  return 'undetermined'
}

