) {

  // 指令：正则正侧可直判；问题不得正则认定
  const st = useAttentionIo.getState()
  // path 配对监督：有挂起时，「跳过匹配 / 监督匹配 / 纯“监督”」走配对，不走归因两轨
  if (
    st.pendingPathMatch &&
    (/跳过匹配|监督匹配/.test(t) || /^监督\s*$/.test(t))
  ) {
    return {
      type: 'ask_user',
      prompt:
        'path 匹配：请在图上高亮 infer×prospect 后确认匹配；或说「跳过匹配」以触发监督 LLM（需有 pending）。',
    }
  }
  // 监督归因：预测轨 vs 狭义推理轨（需台账已有 prospect/infer）
  // 不含光秃「监督」（上面已分流）；「监督归因 / 不满 / …」才归因
  if (
    /监督归因|归因|不满|推理不对|预测不对|材料不够|换方向|换推|换问|改问|问法不对/.test(t) ||
    (/监督/.test(t) && !/跳过匹配|监督匹配|^监督\s*$/.test(t))
  ) {
    const qk =
      st.pendingPathMatch?.queryKey ||
      st.selectedQueryKey ||
      (st.selectedInferKey
        ? st.inferEdges.find((e) => e.inferKey === st.selectedInferKey)
            ?.queryKey
        : undefined) ||
      Object.keys(st.settledQueries).slice(-1)[0]
    if (qk && (st.prospects.length > 0 || st.inferEdges.length > 0)) {
      return {
        type: 'critique',
        queryKey: qk,
        note: '监督归因 · 预测 vs 狭义推理',
      }
    }
    return {
      type: 'ask_user',
      prompt:
        '监督归因需要本问已有 prospect/infer。请先跑自动流，或钉住 query/infer。',
    }
  }
  // 单启某 LLM / 调显
  if (/跳过匹配|监督匹配/.test(t)) {
    return {
      type: 'ask_user',
      prompt:
        'path 匹配：请在图上高亮 infer×prospect 后确认匹配；或说「跳过匹配」以触发监督 LLM（需有 pending）。',
    }
  }
  if (/peek|铸贴/.test(t)) {
    return {
      type: 'dispatch',
      packages: [
        {
          id: sid(),
          edgeId: `cmd_peek_${sid()}`,
          bookKey: '',
          briefKey: '',
          question: t,
          job: 'peek',
          versionIndex: 0,
          createdAt: Date.now(),
        },
      ],
    }
  }
  if (/decide|决策/.test(t)) {
    return {
      type: 'dispatch',
      packages: [
        {
          id: sid(),
          edgeId: `cmd_decide_${sid()}`,
          bookKey: '',
          briefKey: '',
          question: t,
          job: 'decide',
          versionIndex: 0,
          createdAt: Date.now(),
        },
      ],
    }
  }
  if (/infer|推理|主推理/.test(t)) {
    return {
      type: 'dispatch',
      packages: [
        {
          id: sid(),
          edgeId: `cmd_infer_${sid()}`,
          bookKey: '',
          briefKey: '',
          question: t,
          job: 'infer',
          versionIndex: 0,
          createdAt: Date.now(),
        },
      ],
    }
  }
  if (/query|邻域|历史问/.test(t)) {
    return {
      type: 'dispatch',
      packages: [
        {
          id: sid(),
          edgeId: `cmd_query_${sid()}`,
          bookKey: '',
          briefKey: '',
          question: t,
          job: 'query',
          versionIndex: 0,
          createdAt: Date.now(),
        },
      ],
    }
  }
  if (/显示|调取|打开|展开/.test(t)) {
    return {
      type: 'show',
      prompt: `指令·调显：${t.slice(0, 120)}（请钉住对应 key 的注意力窗查看）`,
    }
  }
  return {
    type: 'ask_user',
    prompt:
      '识别为指令。请说明要：调显某内容，或单启 peek / decide / infer / query；path 可「确认匹配」或「跳过匹配」。',
  }
}

